def deduplicate(items):
    """Return items without repeated values, keeping the first occurrence."""
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple")
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

